        if(JOptionPane.showConfirmDialog(DialogPosition.owner(dialogOwner()),form,tr("Programar tarea: ")+tr(kind(kind)),JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;ConnectionProfile selected=(ConnectionProfile)connection.getSelectedItem();char[] secret=password.getPassword();
        if(kind==ScheduledTasks.Kind.SQL&&(!authorized.isSelected()||selected.readOnly())){Arrays.fill(secret,'\0');error(new IllegalArgumentException(tr("Autoriza el script y utiliza una conexión habilitada para escritura.")));return;}if(kind==ScheduledTasks.Kind.BACKUP&&!SqlBackupService.supported(selected.type())){Arrays.fill(secret,'\0');error(new IllegalArgumentException(tr("El respaldo SQL requiere MySQL o MariaDB.")));return;}String previousStatus=previous==null?"":engine.state(previous.id()).status();if(requiresCredentialReentry(previousStatus,secret,selected.authenticationMode())){Arrays.fill(secret,'\0');error(new IllegalArgumentException(tr("El servidor rechazó la contraseña anterior. Escribe nuevamente la contraseña actual del usuario de la base ")+selected.username()+tr(". No uses la clave de Windows ni el nombre de la base.")));return;}
